<script setup lang="ts">
import {onBeforeUnmount,onMounted,ref} from 'vue'
import {getProductImageContent,getProductImages,getProducts,getVariants,updateProduct,uploadProductImage,type Product,type Variant} from '@/services/business'
import {useAuthStore} from '@/stores/auth'

const auth=useAuthStore(),products=ref<Product[]>([]),variants=ref<Variant[]>([]),search=ref(''),loading=ref(false),error=ref('')
const imageUrls=ref<Record<string,string>>({}),imageCounts=ref<Record<string,number>>({}),uploading=ref<string|null>(null),notice=ref('')
const editing=ref<Product|null>(null),saving=ref(false)

function clearImages(){Object.values(imageUrls.value).forEach(URL.revokeObjectURL);imageUrls.value={};imageCounts.value={}}
async function loadImages(){clearImages();await Promise.all(products.value.map(async product=>{try{const images=await getProductImages(product.id);imageCounts.value[product.id]=images.length;if(images[0]){const blob=await getProductImageContent(images[0].id);imageUrls.value[product.id]=URL.createObjectURL(blob)}}catch{/* Product rows remain usable if media is temporarily unavailable. */}}))}
async function load(){loading.value=true;error.value='';try{products.value=(await getProducts(search.value)).items;variants.value=await getVariants();await loadImages()}catch{error.value='Không thể tải danh mục sản phẩm.'}finally{loading.value=false}}
async function selectImage(product:Product,event:Event){const input=event.target as HTMLInputElement,file=input.files?.[0];if(!file)return;notice.value='';error.value='';uploading.value=product.id;try{await uploadProductImage(product.id,file);notice.value=`Đã tải ảnh cho ${product.name}.`;await loadImages()}catch{error.value='Không thể tải ảnh. Chỉ chấp nhận PNG/JPEG hợp lệ trong giới hạn dung lượng.'}finally{uploading.value=null;input.value=''}}
function edit(product:Product){editing.value={...product}}
async function save(){if(!editing.value)return;saving.value=true;error.value='';try{const updated=await updateProduct(editing.value);const index=products.value.findIndex(product=>product.id===updated.id);if(index>=0)products.value[index]=updated;notice.value=`Đã cập nhật ${updated.name}.`;editing.value=null}catch{error.value='Không thể cập nhật. Dữ liệu có thể đã được người khác thay đổi; hãy tải lại và thử lại.'}finally{saving.value=false}}
onMounted(load);onBeforeUnmount(clearImages)
</script>

<template>
  <section class="p-6 lg:p-8">
    <div class="flex flex-wrap items-end justify-between gap-4"><div><p class="text-sm font-semibold text-cyan-700">Danh mục hàng hóa</p><h2 class="text-3xl font-bold">Sản phẩm & SKU</h2></div><form class="flex gap-2" @submit.prevent="load"><input v-model.trim="search" placeholder="Mã hoặc tên…" class="rounded-lg border px-3 py-2"/><button class="rounded-lg bg-slate-900 px-4 py-2 text-white">Tìm</button></form></div>
    <p v-if="notice" role="status" class="mt-4 rounded-lg bg-emerald-50 p-3 text-emerald-800">{{notice}}</p>
    <form v-if="editing" class="mt-4 grid gap-3 rounded-xl border bg-white p-4 md:grid-cols-4" @submit.prevent="save"><label class="text-sm">Tên<input v-model.trim="editing.name" required maxlength="250" class="mt-1 w-full rounded-lg border p-2"/></label><label class="text-sm">Bảo hành (tháng)<input v-model.number="editing.warrantyMonths" required min="0" type="number" class="mt-1 w-full rounded-lg border p-2"/></label><label class="text-sm">Trạng thái<select v-model="editing.status" class="mt-1 w-full rounded-lg border p-2"><option value="ACTIVE">Đang hoạt động</option><option value="INACTIVE">Ngừng hoạt động</option><option value="DISCONTINUED">Ngừng kinh doanh</option></select></label><div class="flex items-end gap-2"><button :disabled="saving" class="rounded-lg bg-cyan-700 px-4 py-2 text-white">{{saving?'Đang lưu…':'Lưu'}}</button><button type="button" class="rounded-lg border px-4 py-2" @click="editing=null">Hủy</button></div></form>
    <p v-if="loading" class="mt-8">Đang tải…</p><p v-else-if="error" class="mt-8 rounded-lg bg-red-50 p-4 text-red-800">{{error}}</p>
    <div v-else class="mt-6 overflow-x-auto rounded-xl border bg-white"><table class="w-full text-left text-sm"><thead class="bg-slate-50"><tr><th class="p-4">Sản phẩm</th><th class="p-4">Phân loại</th><th class="p-4">SKU</th><th class="p-4">Ảnh</th><th class="p-4">Trạng thái</th></tr></thead><tbody class="divide-y"><tr v-for="p in products" :key="p.id"><td class="p-4"><div class="flex items-center gap-3"><img v-if="imageUrls[p.id]" :src="imageUrls[p.id]" :alt="p.name" class="h-14 w-14 rounded-lg border object-cover"/><div v-else class="grid h-14 w-14 place-items-center rounded-lg border bg-slate-50 text-xs text-slate-400">Chưa có ảnh</div><div><b>{{p.name}}</b><p class="font-mono text-xs">{{p.productCode}}</p></div></div></td><td class="p-4">{{p.categoryName}}<span v-if="p.brandName"> · {{p.brandName}}</span></td><td class="p-4"><div v-for="v in variants.filter(x=>x.productId===p.id)" :key="v.id" class="mb-1"><span class="font-mono">{{v.sku}}</span> — {{Number(v.sellingPrice).toLocaleString()}} {{v.currency}}</div><span v-if="!variants.some(x=>x.productId===p.id)" class="text-slate-400">Chưa có SKU</span></td><td class="p-4"><p class="mb-2 text-xs text-slate-500">{{imageCounts[p.id]??0}} ảnh</p><label v-if="auth.hasPermission('product.update')" class="cursor-pointer rounded-md border px-3 py-2 text-xs font-semibold hover:bg-slate-50"><span>{{uploading===p.id?'Đang tải…':'Tải PNG/JPEG'}}</span><input type="file" accept="image/png,image/jpeg" class="sr-only" :disabled="uploading!==null" @change="selectImage(p,$event)"/></label></td><td class="p-4"><p><StatusBadge :value="p.status" /></p><button v-if="auth.hasPermission('product.update')" class="mt-2 text-xs font-semibold text-cyan-700" @click="edit(p)">Chỉnh sửa</button></td></tr></tbody></table></div>
  </section>
</template>
